python3 -c "
import json
d = json.load(open('/tmp/clauses_supplement.json'))
assert len(d) == 40, f'Expected 40, got {len(d)}'
types = {}
for c in d:
    types[c['ambiguity_type']] = types.get(c['ambiguity_type'], 0) + 1
assert types == {'lexical': 20, 'incompleteness': 20}, f'Wrong distribution: {types}'
fields = ['ambiguous_clause','unambiguous_clause','user_scenario','tools','tool_responses']
assert all(all(f in c for f in fields) for c in d), 'Missing fields'
print(f'OK: {types}')

# Additional checks
all_fields = ['clause_id', 'ambiguity_type', 'ambiguous_clause', 'unambiguous_clause', 'user_scenario', 'tools', 'stripped_tool_desc', 'tool_responses', 'ambiguity_point', 'possible_interpretations', 'expected_agent_behavior_diff']
missing = []
for c in d:
    for f in all_fields:
        if f not in c:
            missing.append((c['clause_id'], f))
if missing:
    print(f'Missing fields: {missing}')
else:
    print('All extended fields present')

# Check tool_responses >= 3
low = [(c['clause_id'], len(c['tool_responses'])) for c in d if len(c['tool_responses']) < 3]
if low:
    print(f'Low tool_responses: {low}')
else:
    print('All clauses have >= 3 tool_responses')

# Domain balance
for t in ['lexical', 'incompleteness']:
    doms = {}
    for c in d:
        if c['ambiguity_type'] == t:
            doms[c['domain']] = doms.get(c['domain'], 0) + 1
    print(f'{t} domains: {doms}')

# Check clause_id sequence
lex_ids = sorted([c['clause_id'] for c in d if c['ambiguity_type'] == 'lexical'])
inc_ids = sorted([c['clause_id'] for c in d if c['ambiguity_type'] == 'incompleteness'])
print(f'Lexical IDs: {lex_ids[0]} .. {lex_ids[-1]}')
print(f'Incompleteness IDs: {inc_ids[0]} .. {inc_ids[-1]}')
"

